def real_records(ctx: Ctx) -> list[Path]:
    """Файлы записей, пригодные для render/to_db: не skeleton."""
    out = []
    for p in sorted(ctx.records.rglob("*.yaml")) if ctx.records.exists() else []:
        if "design" in p.relative_to(ctx.records).parts[:-1]:
            continue  # разборы design: другая схема, грузятся mechanics-db/ingest_design.py
        try:
            d = yaml.load(p.read_text(encoding="utf-8"), Loader=Loader) or {}
        except Exception:
            continue
        if d.get("status", "draft") != "skeleton":
            out.append(p)
    return out


def is_auto_file(p: Path) -> bool:
    with p.open(encoding="utf-8") as f:
        return f.readline().startswith("# AUTO-GENERATED")


def step_render(ctx: Ctx):
    files = real_records(ctx)
    authored = [p for p in files if not is_auto_file(p)]
    auto = [p for p in files if is_auto_file(p)]
    spec, spec_auto = ctx.work / "spec", ctx.work / "spec_auto"

    def fn():
        if not files:
            return "skipped", "нет записей вне статуса skeleton"
        n = []
        for grp, out in ((authored, spec), (auto, spec_auto)):   # авто-данные отдельно: verify их не касается
            if grp:
                sh([sys.executable, KIT / "records" / "render.py", "--records", *grp, "--out", out, "--skip-skeleton"])
                n.append(f"{len(list(out.glob('*.md')))} md -> {out.name}")
        return "ok", "; ".join(n)
    return run_step(ctx, "render", fp_paths(*files, KIT / "records" / "render.py"), lambda: bool(files) and (spec.exists() or spec_auto.exists()), fn)


def step_verify(ctx: Ctx):
    spec = ctx.work / "spec"
    manual = Path(ctx.a.spec_dir) if ctx.a.spec_dir else None   # ручная спека игры: отчёт отдельно от рендера
    script = KIT / "verify" / "verify_numbers.py"

    def one(src, out):
        sh([sys.executable, script, "--spec", src, "--index", ctx.index_json, "--data", ctx.ref / "data", "--out-dir", out])

    def fn():
        if not script.exists():
            return "skipped", "verify/verify_numbers.py не найден"
        notes = []
        if list(spec.glob("*.md")):
            one(spec, ctx.work / "verify")
            notes.append(f"рендер -> {ctx.work / 'verify'}")
        if manual:
            if not list(manual.glob("*.md")):
                return "error", f"--spec-dir без .md: {manual}"
            one(manual, ctx.work / "verify_manual")
            notes.append(f"ручная -> {ctx.work / 'verify_manual'}")
        return ("ok", "; ".join(notes)) if notes else ("skipped", "нет отрендеренных спек")
    return run_step(ctx, "verify", fp_paths(spec, manual, ctx.index_json, script),
                    lambda: (ctx.work / "verify").exists() and (not manual or (ctx.work / "verify_manual").exists()), fn)


def step_to_db(ctx: Ctx):
    files = real_records(ctx)
    out = ctx.work / "entries.jsonl"

    def fn():
        if not files:
            return "skipped", "нет записей вне статуса skeleton"
        cmd = [sys.executable, KIT / "records" / "to_db.py", "--records", *files, "--jsonl", out]
        if ctx.a.db:
            cmd += ["--db", ctx.a.db]
        sh(cmd)
        return "ok", f"{out}" + (f" + {ctx.a.db}" if ctx.a.db else "")
    return run_step(ctx, "to_db", fp_paths(*files) + str(ctx.a.db), lambda: out.exists() and not ctx.a.db, fn)


